export type I18nPiece = {
    type: 'raw';
    value: string;
} | {
    type: 'ph';
    rawInner: string;
    key: string;
};
/**
 * 栈式解析 #{ ... } 占位。支持内部成对花括号，如 #{ foo {{ bar }} }。
 * - 未闭合时：把从上次位置 i 到结尾整体作为 raw 放回（避免被拆成两段）
 * - key = trim(rawInner)
 */
export declare const parseI18n: (text: string) => I18nPiece[];
